package pzvrphysicality;
import java.lang.reflect.*;import java.util.*;import zombie.core.skinnedmodel.model.ModelMesh;import zombie.core.skinnedmodel.model.VertexBufferObject;

/** Original hand-bag vertex/weight copies before native upload; no model, palette or inventory mutation. */
public final class BackpackMeshCpu {
 public record Data(float[] positions,int[] faces,float[] weights,int[] joints){
  public Data{if(positions==null||faces==null||weights==null||joints==null||positions.length<12||positions.length%3!=0||positions.length>24576||faces.length<3||faces.length%3!=0||faces.length>24576||weights.length!=positions.length/3*4||joints.length!=weights.length)throw new IllegalArgumentException("Backpack skin extent");positions=positions.clone();faces=faces.clone();weights=weights.clone();joints=joints.clone();for(float p:positions)if(!Float.isFinite(p)||Math.abs(p)>10000)throw new IllegalArgumentException("Backpack raw coordinate");for(int f:faces)if(f<0||f>=positions.length/3)throw new IllegalArgumentException("Backpack skin face");for(int v=0;v<positions.length/3;v++){double sum=0;for(int k=0;k<4;k++){int at=v*4+k;float w=weights[at];if(!Float.isFinite(w)||w<0||w>1.002f||w>0&&(joints[at]<0||joints[at]>=4096))throw new IllegalArgumentException("Backpack skin influence");sum+=w;}if(sum>4.01)throw new IllegalArgumentException("Backpack skin sum");}}
  public float[] positions(){return positions.clone();}public int[] faces(){return faces.clone();}public float[] weights(){return weights.clone();}public int[] joints(){return joints.clone();}
  int bytes(){return (positions.length+faces.length+weights.length+joints.length)*4;}
  int bones(){int max=-1;for(int i=0;i<weights.length;i++)if(weights[i]>0)max=Math.max(max,joints[i]);return max+1;}
 }
 private static final WeakHashMap<ModelMesh,Data> cache=new WeakHashMap<>();
 public static boolean allowed(String path){if(path==null||path.length()>512||path.indexOf('\0')>=0)return false;var p=path.replace('\\','/').toLowerCase(Locale.ROOT);if(p.contains("..")||p.contains(":")||p.contains("?")||p.contains("#"))return false;int at=p.indexOf("skinned/backpacks/");if(at<0||at>0&&p.charAt(at-1)!='/')return false;String name=p.substring(at+18);if(name.contains("/"))return false;name=name.replaceFirst("\\.(x|fbx|glb|txt)$","");return name.endsWith("_lhand")||name.endsWith("_rhand");}
 private static Object read(Object value,String name)throws ReflectiveOperationException{var f=value.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(value);}
 public static void capture(Object loaded,ModelMesh target){if(target!=null)retire(target);if(!Main.ready()||target==null||loaded==null)return;try{if(target.getPath()==null||!allowed(target.getPath().getPath()))return;Object source=loaded;String type=loaded.getClass().getName();if(type.equals("zombie.core.skinnedmodel.model.ModelTxt")){if(Boolean.TRUE.equals(read(loaded,"isStatic")))return;}else if(type.equals("zombie.core.skinnedmodel.model.jassimp.ProcessedAiScene")){source=read(loaded,"skinnedMesh");if(source==null||!source.getClass().getName().equals("zombie.core.skinnedmodel.model.jassimp.ImportedSkinnedMesh"))return;}else return;
  var vertices=(VertexBufferObject.VertexArray)read(source,"vertices");var faces=(int[])read(source,"elements");if(vertices==null||vertices.numVertices<4||vertices.numVertices>8192)throw new IllegalArgumentException("Backpack preupload budget");var format=vertices.format;if(format==null)throw new IllegalArgumentException("Backpack vertex format");int p=format.indexOf(VertexBufferObject.VertexType.VertexArray),w=format.indexOf(VertexBufferObject.VertexType.BlendWeightArray),j=format.indexOf(VertexBufferObject.VertexType.BlendIndexArray);if(p<0||w<0||j<0||format.getElement(p).byteSize!=12||format.getElement(w).byteSize!=16||format.getElement(j).byteSize!=16)throw new IllegalArgumentException("Backpack vertex layout");int stride=format.getStride();var ranges=new ArrayList<int[]>();for(int index:new int[]{p,w,j}){var e=format.getElement(index);if(e.byteOffset<0||e.byteOffset+e.byteSize>stride)throw new IllegalArgumentException("Backpack vertex range");for(var old:ranges)if(e.byteOffset<old[1]&&old[0]<e.byteOffset+e.byteSize)throw new IllegalArgumentException("Backpack overlapping attributes");ranges.add(new int[]{e.byteOffset,e.byteOffset+e.byteSize});}
  float[] positions=new float[vertices.numVertices*3],weights=new float[vertices.numVertices*4];int[] joints=new int[weights.length];for(int v=0;v<vertices.numVertices;v++){for(int axis=0;axis<3;axis++)positions[v*3+axis]=vertices.getElementFloat(v,p,axis);for(int k=0;k<4;k++){int at=v*4+k;weights[at]=vertices.getElementFloat(v,w,k);if(weights[at]>0){float bone=vertices.getElementFloat(v,j,k);if(!Float.isFinite(bone)||bone!=Math.rint(bone)||bone<0||bone>=4096)throw new IllegalArgumentException("Backpack float bone index");joints[at]=(int)bone;}}}offer(target,new Data(positions,faces,weights,joints));
 }catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){/* The native loader continues; unavailable geometry keeps the original inventory UI. */}}
 public static synchronized void offer(ModelMesh mesh,Data data){Objects.requireNonNull(mesh);Objects.requireNonNull(data);int bytes=cache.values().stream().mapToInt(Data::bytes).sum();var old=cache.get(mesh);if(old!=null)bytes-=old.bytes();if(cache.size()>=64&&!cache.containsKey(mesh)||bytes+data.bytes()>8*1024*1024)cache.clear();cache.put(mesh,data);}
 public static synchronized Data get(ModelMesh mesh){return cache.get(mesh);}public static synchronized void retire(ModelMesh mesh){if(mesh!=null)cache.remove(mesh);}
 /** Native weighted vec4 rows. Active bones, rather than buffer capacity, bound every used index. */
 public static float[] skin(Data data,float[] palette,int start,int activeBones){Objects.requireNonNull(data);var positions=data.positions();if(start<0)return positions;if(palette==null||activeBones<0||activeBones>4096||palette.length<activeBones*12||palette.length%12!=0||start>activeBones)throw new IllegalArgumentException("Backpack active palette extent");for(int v=0;v<positions.length/3;v++){double x=0,y=0,z=0;boolean weighted=false;for(int k=0;k<4;k++){int at=v*4+k;float weight=data.weights[at];if(weight<=0)continue;weighted=true;int bone=start+data.joints[at];if(bone<0||bone>=activeBones)throw new IllegalArgumentException("Backpack active bone index");int row=bone*12;for(int c=0;c<12;c++)if(!Float.isFinite(palette[row+c]))throw new IllegalArgumentException("Backpack current skin row");double px=data.positions[v*3],py=data.positions[v*3+1],pz=data.positions[v*3+2];x+=weight*(palette[row]*px+palette[row+1]*py+palette[row+2]*pz+palette[row+3]);y+=weight*(palette[row+4]*px+palette[row+5]*py+palette[row+6]*pz+palette[row+7]);z+=weight*(palette[row+8]*px+palette[row+9]*py+palette[row+10]*pz+palette[row+11]);}if(weighted){positions[v*3]=(float)x;positions[v*3+1]=(float)y;positions[v*3+2]=(float)z;if(!Float.isFinite(positions[v*3])||!Float.isFinite(positions[v*3+1])||!Float.isFinite(positions[v*3+2]))throw new IllegalArgumentException("Backpack skin overflow");}}return positions;}
 /** Copies only the original bag's used current rows from a potentially large scene palette. */
 public static UtensilContact.Geometry posed(Data data,float[] source,int base,int activeBones){if(base<0)return new UtensilContact.Geometry(data.positions(),data.faces());int needed=data.bones();if(source==null||activeBones<0||base<0||base>activeBones||needed>activeBones-base||source.length/12<activeBones||activeBones>100000)throw new IllegalArgumentException("Backpack scene palette extent");var rows=Arrays.copyOfRange(source,base*12,(base+needed)*12);return new UtensilContact.Geometry(skin(data,rows,0,needed),data.faces());}
 private BackpackMeshCpu(){}
}
